import sys
import re

def parse_molecule(molecule):
    pattern = r'([A-Z])(\d*)'
    matches = re.findall(pattern, molecule)
    atom_count = {}
    for atom, count in matches:
        if count == '':
            count = 1
        else:
            count = int(count)
        if atom in atom_count:
            atom_count[atom] += count
        else:
            atom_count[atom] = count
    return atom_count

def max_molecules(input_molecule, input_count, output_molecule):
    input_atoms = parse_molecule(input_molecule)
    output_atoms = parse_molecule(output_molecule)

    min_ratio = float('inf')

    for atom in output_atoms:
        if atom not in input_atoms:
            return 0
        min_ratio = min(min_ratio, input_atoms[atom] // output_atoms[atom])

    return min(input_count, min_ratio)

def main():
    input_data = sys.stdin.read().strip().split()
    input_molecule = ''.join(input_data[:-1])
    input_count = int(input_data[-1])
    output_molecule = sys.stdin.readline().strip()

    result = max_molecules(input_molecule, input_count, output_molecule)
    print(result)

if __name__ == "__main__":
    main()
